"""Scratch verification for hotspot_kind_summary."""
import json
from fractions import Fraction
from itertools import product

from urban_micro import hotspot_plan, hotspot_kind_summary
from urban_micro import uhi as _uhi


def _priority(specs, alpha=0.05):
    hotspots, effects = [], {}
    for index, (pick, by, key, effect, q) in enumerate(specs):
        hotspots.append(
            '{"pick":'
            + json.dumps(list(pick), separators=(",", ":"))
            + f',"by":"{by}","key":"{key}","steps":10,"hits":10,'
            + f'"max_abs":{index + 1},"persistence":1.000000}}'
        )
        effects[(tuple(pick), by, key)] = (effect, q)
    rank = f'{{"alpha":{alpha:.6f},"hotspots":[{",".join(hotspots)}]}}\n'
    return _uhi.rank_hotspot_priority(rank, effects)


def reference(spec_rows, alpha=0.05):
    """spec_rows: list of (pick, by, key, effect, w). Returns expected payload."""
    # cell: (by, kind) -> list of (w, v)
    cells = {}
    panel_w = {}
    # aggregate per panel/kind effects
    panel_kind = {}
    for pick, by, key, effect, w in spec_rows:
        panel_w[(by, key)] = w
        d = panel_kind.setdefault((by, key), {})
        for kind in pick:
            d[kind] = d.get(kind, Fraction(0)) + Fraction(str(effect))
    for (by, key), kinds in panel_kind.items():
        for kind, v in kinds.items():
            cells.setdefault((by, kind), []).append(
                (Fraction(str(panel_w[(by, key)])), v)
            )
    items = []
    for (by, kind), panels in cells.items():
        W = sum((w for w, _ in panels), Fraction(0))
        contrib = [w * v / W for w, v in panels]
        change = sum(contrib, Fraction(0))
        n = len(panels)
        tail = 0
        for signs in product((-1, 1), repeat=n):
            stat = sum(s * c for s, c in zip(signs, contrib))
            if abs(stat) >= abs(change):
                tail += 1
        p = Fraction(tail, 1 << n)
        items.append([by, kind, n, change, p])
    items.sort(key=lambda r: (r[4], 0 if r[0] == "region" else 1, r[1]))
    N = len(items)
    qs = []
    running = Fraction(1)
    for rank in range(N, 0, -1):
        running = min(running, N * items[rank - 1][4] / rank)
        qs.insert(0, min(Fraction(1), running))
    result = {}
    for row, q in zip(items, qs):
        by, kind, n, change, p = row
        result[(by, kind)] = (n, change, p, q)
    return result


def build_plan(specs, cost, limit, allow):
    priority = _priority(specs)
    return hotspot_plan(priority, cost, limit, allow)


def check(name, specs, plan_effects_select, weights, cost, limit, allow, alpha=0.05):
    plan = build_plan(specs, cost, limit, allow)
    out = hotspot_kind_summary(plan, plan_effects_select, weights)
    assert out.endswith("\n") and not out.endswith("\n\n"), repr(out)
    assert " " not in out, repr(out)
    payload = json.loads(out)
    assert list(payload) == ["alpha", "groups"]
    # compare to reference built from SELECTED picks only
    selected_rows = []
    pdata = json.loads(plan)
    sel = set()
    for g in pdata["groups"]:
        for pk in g["pick"]:
            sel.add((g["by"], g["key"], tuple(pk)))
    for (by, key, pick), val in plan_effects_select.items():
        selected_rows.append((pick, by, key, val, weights[(by, key)]))
    expected = reference(selected_rows, alpha)
    # group structure
    bys = [g["by"] for g in payload["groups"]]
    assert bys == sorted(bys), bys
    got = {}
    for g in payload["groups"]:
        assert list(g) == ["by", "items"]
        kinds = [it["kind"] for it in g["items"]]
        assert kinds == sorted(kinds), kinds
        for it in g["items"]:
            assert list(it) == ["kind", "n", "change", "p", "q", "reject"]
            assert isinstance(it["n"], int) and isinstance(it["reject"], bool)
            got[(g["by"], it["kind"])] = it
    assert set(got) == set(expected), (set(got), set(expected))
    for key, it in got.items():
        n, change, p, q = expected[key]
        assert it["n"] == n
        assert abs(it["change"] - float(change)) < 1e-6, (key, it, change)
        assert abs(it["p"] - float(p)) < 1e-6, (key, it, p)
        assert abs(it["q"] - float(q)) < 1e-6, (key, it, q)
        assert it["reject"] is (q <= Fraction(str(alpha))), key
    print(f"PASS {name}: {out.strip()}")
    return out


