empty = '{"alpha":0.050000,"groups":[]}\n'
assert hotspot_kind_summary(empty, {}, {}) == empty
for bad_e, bad_w in [({("region", "R1"): 1.0}, {}), ({}, {("region", "R1"): 1.0})]:
    try:
        hotspot_kind_summary(empty, bad_e, bad_w)
        raise AssertionError("should raise")
    except ValueError:
        pass
print("PASS empty")

# type errors
