specs = [(("green",), "region", "R1", -1.0, 0.01)]
plan = build_plan(
    specs,
    {("green",): 1.0},
    {("region", "R1"): 3.0},
    {("region", "R1"): [("green",)]},
)
out = hotspot_kind_summary(plan, {("region", "R1", ("green",)): -2.0}, {("region", "R1"): 1.0})
print("single:", out.strip())
d = json.loads(out)
assert d["groups"][0]["by"] == "region"
it = d["groups"][0]["items"][0]
assert it == {"kind": "green", "n": 1, "change": -2.0, "p": 1.0, "q": 1.0, "reject": False}, it

# --- multi-kind pick: effect counted per kind ---
specs = [(("green", "roof"), "region", "R1", -3.0, 0.01)]
plan = build_plan(
    specs,
    {("green", "roof"): 1.0},
    {("region", "R1"): 3.0},
    {("region", "R1"): [("green", "roof")]},
)
out = hotspot_kind_summary(
    plan, {("region", "R1", ("green", "roof")): -4.0}, {("region", "R1"): 2.0}
)
print("multikind:", out.strip())
d = json.loads(out)
kinds = [it["kind"] for it in d["groups"][0]["items"]]
assert kinds == ["green", "roof"]
for it in d["groups"][0]["items"]:
    assert it["change"] == -4.0 and it["n"] == 1 and it["p"] == 1.0

# --- two picks in one panel sharing a kind: effects sum ---
specs = [
    (("green",), "region", "R1", -1.0, 0.01),
    (("green", "roof"), "region", "R1", -3.0, 0.02),
]
plan = build_plan(
    specs,
    {("green",): 1.0, ("green", "roof"): 1.0},
    {("region", "R1"): 5.0},
    {("region", "R1"): [("green",), ("green", "roof")]},
)
# plan may select both; effects
pdata = json.loads(plan)
print("plan picks R1:", pdata["groups"][0]["pick"])
eff = {}
for g in pdata["groups"]:
    for pk in g["pick"]:
        eff[(g["by"], g["key"], tuple(pk))] = -1.5 if tuple(pk) == ("green",) else -2.5
out = hotspot_kind_summary(plan, eff, {("region", "R1"): 1.0})
print("shared kind:", out.strip())

# --- richer multi-panel check against rational reference ---
specs = [
    (("green",), "region", "R1", -1.0, 0.001),
    (("roof",), "region", "R1", -2.0, 0.002),
    (("green", "roof"), "region", "R2", -3.0, 0.003),
    (("material",), "window", "W1", -1.0, 0.004),
    (("green",), "window", "W2", 1.0, 0.9),
]
all_picks = {(p,) if isinstance(p, str) else p for p, *_ in
             [((s[0],), None) for s in []]}
picks = {tuple(s[0]) for s in specs}
cost = {pick: 1.0 for pick in picks}
limit = {}
allow = {}
for pick, by, key, *_ in specs:
    limit[(by, key)] = 10.0
    allow.setdefault((by, key), []).append(list(pick))
plan = build_plan(specs, cost, limit, allow)
pdata = json.loads(plan)
eff = {}
valmap = {
    ("region", "R1", ("green",)): -1.5,
    ("region", "R1", ("roof",)): -2.0,
    ("region", "R2", ("green", "roof")): -3.5,
    ("window", "W1", ("material",)): -4.0,
    ("window", "W2", ("green",)): 0.75,
