for g in pdata["groups"]:
    for pk in g["pick"]:
        triple = (g["by"], g["key"], tuple(pk))
        eff[triple] = valmap[triple]
weights = {
    ("region", "R1"): 1.0,
    ("region", "R2"): 2.0,
    ("window", "W1"): 1.0,
    ("window", "W2"): 1.0,
}
check("rich", specs, eff, weights, cost, limit, allow)

# --- n > 16 across a by dimension for one kind ---
specs17 = [
    ((("green",), "region", f"R{i:02d}", -1.0, 0.01)) for i in range(17)
]
picks17 = {tuple(s[0]) for s in specs17}
cost17 = {pick: 1.0 for pick in picks17}
limit17 = {(by, key): 10.0 for _, by, key, *_ in specs17}
allow17 = {(by, key): [list(specs17[i][0])] for i, (_, by, key, *__) in
